import SwiftUI
import SwiftData
import RevenueCat

@main
struct PlantScannerApp: App {

    // MARK: - Properties

    let modelContainer: ModelContainer
    let dependencies: DependenciesSupporting
    let coordinator: CoordinatorSupporting

    #if os(iOS)
    @UIApplicationDelegateAdaptor(AppDelegate.self) var delegate
    #elseif os(macOS)
    @NSApplicationDelegateAdaptor(AppDelegate.self) var delegate
    #endif

    @Environment(\.scenePhase) var scenePhase

    // MARK: - Init

    init() {
        // Configure RevenueCat
        Purchases.configure(
            with: .builder(withAPIKey: AppConfig.revenueCatApiKey)
                .with(purchasesAreCompletedBy: .revenueCat, storeKitVersion: .storeKit2)
                .build()
        )

        #if DEBUG
        Purchases.logLevel = .verbose
        #endif

        do {
            self.modelContainer = try ModelContainer(
                for: PlantEntity.self,
                CareTaskEntity.self,
                CareLogEntity.self,
                CareNoteEntity.self,
                migrationPlan: PlantScannerMigrationPlan.self
            )
        } catch {
            fatalError("Could not create ModelContainer: \(error)")
        }

        let dependencies = Dependencies(modelContainer: modelContainer)
        self.dependencies = dependencies
        self.coordinator = Coordinator(dependencies: dependencies)

        Self.configureNavigationBarAppearance()
    }

    /// Sets serif (New York) font for all navigation bar titles globally.
    private static func configureNavigationBarAppearance() {
        #if os(iOS) || os(visionOS)
        let serifInline = Self.serifFont(forTextStyle: .headline, weight: .bold)
        let serifLargeTitle = Self.serifFont(forTextStyle: .largeTitle, weight: .bold)

        let inlineAppearance = UINavigationBarAppearance()
        inlineAppearance.configureWithDefaultBackground()
        inlineAppearance.titleTextAttributes = [.font: serifInline]
        inlineAppearance.largeTitleTextAttributes = [.font: serifLargeTitle]

        let transparentAppearance = UINavigationBarAppearance()
        transparentAppearance.configureWithTransparentBackground()
        transparentAppearance.titleTextAttributes = [.font: serifInline]
        transparentAppearance.largeTitleTextAttributes = [.font: serifLargeTitle]

        UINavigationBar.appearance().standardAppearance = inlineAppearance
        UINavigationBar.appearance().compactAppearance = inlineAppearance
        UINavigationBar.appearance().scrollEdgeAppearance = transparentAppearance
        UINavigationBar.appearance().compactScrollEdgeAppearance = transparentAppearance
        #endif
    }

    #if os(iOS) || os(visionOS)
    private static func serifFont(
        forTextStyle style: UIFont.TextStyle,
        weight: UIFont.Weight
    ) -> UIFont {
        let size = UIFont.preferredFont(forTextStyle: style).pointSize
        let descriptor = UIFontDescriptor.preferredFontDescriptor(withTextStyle: style)
        if let serifDescriptor = descriptor.withDesign(.serif) {
            return UIFont(
                descriptor: serifDescriptor.addingAttributes([
                    .traits: [UIFontDescriptor.TraitKey.weight: weight]
                ]),
                size: size
            )
        }
        return UIFont.systemFont(ofSize: size, weight: weight)
    }
    #endif

    // MARK: - Body

    var body: some Scene {
        WindowGroup {
            coordinator.rootView()
                .preferredColorScheme(.dark)
                .task {
                    await dependencies.subscriptionService.prefetchOfferings()
                }
        }
        .modelContainer(modelContainer)
    }
}

import Foundation
import SwiftData

// MARK: - V1: Original schema (PlantEntity only)

enum PlantScannerSchemaV1: VersionedSchema {

    static var versionIdentifier: Schema.Version { .init(1, 0, 0) }

    static var models: [any PersistentModel.Type] {
        [PlantEntity.self]
    }

    @Model
    final class PlantEntity {
        @Attribute(.unique) var id: UUID
        var commonName: String
        var scientificName: String
        var family: String
        var plantDescription: String
        var careInstructionsData: Data?
        @Attribute(.externalStorage) var imageData: Data?
        var identifiedAt: Date
        var confidence: Double

        init(
            id: UUID = UUID(),
            commonName: String,
            scientificName: String,
            family: String,
            plantDescription: String,
            careInstructionsData: Data? = nil,
            imageData: Data? = nil,
            identifiedAt: Date = .now,
            confidence: Double = 0
        ) {
            self.id = id
            self.commonName = commonName
            self.scientificName = scientificName
            self.family = family
            self.plantDescription = plantDescription
            self.careInstructionsData = careInstructionsData
            self.imageData = imageData
            self.identifiedAt = identifiedAt
            self.confidence = confidence
        }
    }
}

// MARK: - V2: Garden + Care tracking

enum PlantScannerSchemaV2: VersionedSchema {

    static var versionIdentifier: Schema.Version { .init(2, 0, 0) }

    static var models: [any PersistentModel.Type] {
        [
            PlantEntity.self,
            CareTaskEntity.self,
            CareLogEntity.self,
            CareNoteEntity.self
        ]
    }
}
